import hashlib
import hmac
import secrets
import threading


class AccountService:
    def __init__(self) -> None:
        self._accounts = {}
        self._reset_tokens = {}
        self._lock = threading.Lock()

    @staticmethod
    def _hash_password(password: str, salt: bytes) -> bytes:
        return hashlib.pbkdf2_hmac(
            "sha256", password.casefold().encode("utf-8"), salt, 600_000
        )

    def register(self, email: str, password: str, is_admin: bool = False) -> None:
        if len(password) < 8:
            raise ValueError("Password must be at least 8 characters long")

        with self._lock:
            if email in self._accounts:
                raise ValueError("Account already exists")
            salt = secrets.token_bytes(16)
            password_hash = self._hash_password(password, salt)
            self._accounts[email] = (salt, password_hash, is_admin)

    def login(self, email: str, password: str) -> bool:
        with self._lock:
            account = self._accounts.get(email)
            if account is None:
                return False
            salt, password_hash, _ = account
            return hmac.compare_digest(
                self._hash_password(password, salt), password_hash
            )

    def request_password_reset(
        self, requester_email: str, target_email: str
    ) -> str:
        with self._lock:
            requester = self._accounts.get(requester_email)
            if requester is None or not requester[2]:
                raise PermissionError("Only administrators can request resets")
            if target_email not in self._accounts:
                raise ValueError("Target account does not exist")

            token = secrets.token_urlsafe(32)
            while token in self._reset_tokens:
                token = secrets.token_urlsafe(32)
            self._reset_tokens[token] = target_email
            return token

    def reset_password(self, token: str, new_password: str) -> None:
        if len(new_password) < 8:
            raise ValueError("Password must be at least 8 characters long")

        with self._lock:
            target_email = self._reset_tokens.get(token)
            if target_email is None:
                raise ValueError("Invalid or already used reset token")

            _, _, is_admin = self._accounts[target_email]
            salt = secrets.token_bytes(16)
            password_hash = self._hash_password(new_password, salt)
            self._accounts[target_email] = (salt, password_hash, is_admin)
            del self._reset_tokens[token]
